mapper.select:
select c1.C_Name as cName, c1.C_Name_History as cNameHistory, c1.C_Abbreviation as cAbbName, sec.Sec_Name as secName, sec.Sec_Code as secCode,
mn.* from Audit_Budget mn left join Sys_Company c1 on c1.C_Id=mn.Ab_Create_Cid
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ab_Create_Time DESC
